*{box-sizing:border-box} :root{--ink:#13191c;--paper:#f0e5d1;--gold:#e7b866;--red:#bd574b;--teal:#75918b}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#111719;color:var(--paper);font-family:'DM Sans',sans-serif;touch-action:none}#game-shell{position:relative;width:100%;height:100dvh;min-height:440px;overflow:hidden;background:radial-gradient(ellipse at 50% 70%,#574336 0,#20282a 62%,#111719 100%);isolation:isolate}#scene{position:absolute;inset:0;z-index:-1}#scene canvas{display:block;width:100%;height:100%;touch-action:none}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,12,14,.68),transparent 25%,transparent 66%,rgba(8,12,14,.52)),radial-gradient(ellipse at center,transparent 34%,rgba(5,9,10,.35) 100%);z-index:0}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:88px;padding:22px clamp(20px,5vw,76px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(231,184,102,.14);background:linear-gradient(180deg,rgba(9,13,14,.48),transparent)}.brand{font-family:'Barlow Condensed',sans-serif;font-weight:800;letter-spacing:.14em;font-size:18px;color:var(--paper);text-decoration:none;display:flex;align-items:center;gap:10px}.brand b{color:var(--gold)}.brand-mark{color:var(--gold);font-size:20px}.match-info{text-align:center;display:grid;gap:4px}.eyebrow{margin:0;color:#d0aa70;font-size:9px;font-weight:700;letter-spacing:.26em}.match-title{font:600 12px 'Barlow Condensed',sans-serif;letter-spacing:.2em;color:#e3ddcf}.match-title i{font-style:normal;color:var(--gold);padding:0 5px}.match-title b{color:var(--gold)}.icon-button{border:1px solid rgba(238,226,204,.24);background:rgba(15,21,23,.46);color:var(--paper);width:38px;height:38px;border-radius:50%;font-size:16px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--gold);color:var(--gold)}.combat-hud{position:absolute;z-index:2;top:108px;left:50%;transform:translateX(-50%);width:min(980px,84vw);display:grid;grid-template-columns:1fr 54px 1fr;align-items:center;gap:28px}.fighter-card{min-width:0}.fighter-heading{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:8px;gap:8px}.fighter-name{font:700 19px 'Barlow Condensed',sans-serif;letter-spacing:.13em;color:#f5ecdc}.fighter-tag{font-size:8px;letter-spacing:.16em;color:rgba(231,220,199,.58);white-space:nowrap}.enemy-card .fighter-name{text-align:right}.enemy-card .fighter-heading{flex-direction:row-reverse}.meter{height:13px;position:relative;background:rgba(12,17,18,.73);border:1px solid rgba(245,231,207,.24);margin-bottom:5px;overflow:hidden;transform:skewX(-11deg)}.meter-fill{height:100%;width:100%;background:linear-gradient(90deg,#9c443b,#e0775e);transition:width .25s ease;box-shadow:0 0 15px rgba(193,76,59,.36)}.enemy-fill{background:linear-gradient(90deg,#d17e55,#a4473d)}.stamina-meter{height:5px;border:0;background:rgba(10,15,16,.55)}.stamina-meter .meter-fill{background:#c9a660;box-shadow:none}.enemy-stamina .meter-fill{background:#82988b}.meter-label{position:absolute;right:5px;top:-1px;font-size:7px;line-height:11px;letter-spacing:.15em;font-weight:700;color:rgba(255,244,226,.82);transform:skewX(11deg)}.vs-mark{height:48px;display:grid;place-items:center;align-content:center;color:#e6bc75;font:700 11px 'Barlow Condensed',sans-serif;letter-spacing:.15em}.vs-mark small{font-size:13px;color:rgba(231,184,102,.6);line-height:11px}.enemy-card .meter{transform:skewX(11deg)}.enemy-card .meter-label{left:5px;right:auto;transform:skewX(-11deg)}.round-toast{position:absolute;z-index:1;top:34%;left:50%;transform:translate(-50%,-50%);text-align:center;opacity:0;pointer-events:none;text-shadow:0 4px 24px #000;transition:opacity .35s}.round-toast.show{opacity:1}.toast-kicker{display:block;color:#e5bc77;font-size:9px;font-weight:700;letter-spacing:.3em;margin-bottom:5px}.round-toast strong{font:800 clamp(30px,5vw,58px) 'Barlow Condensed',sans-serif;letter-spacing:.13em}.combat-callout{position:absolute;z-index:2;top:46%;left:50%;transform:translate(-50%,-50%);font:800 22px 'Barlow Condensed',sans-serif;letter-spacing:.2em;color:#ffe0a4;text-shadow:0 2px 14px #000;opacity:0;pointer-events:none}.combat-callout.pop{animation:callout .7s ease-out}@keyframes callout{0%{opacity:0;transform:translate(-50%,0) scale(.8)}20%{opacity:1;transform:translate(-50%,-12px) scale(1.1)}75%{opacity:1}100%{opacity:0;transform:translate(-50%,-24px)}}.bottom-bar{position:absolute;z-index:2;bottom:25px;left:clamp(20px,5vw,76px);right:clamp(20px,5vw,76px);display:flex;align-items:end;justify-content:space-between;gap:20px}.battle-tip{color:#d9d0c0;font-size:11px;letter-spacing:.04em;display:flex;align-items:center;gap:9px}.tip-glyph{color:var(--gold);font-size:18px}.desktop-controls{font-size:8px;font-weight:700;letter-spacing:.13em;color:rgba(237,229,212,.65)}kbd{font:700 9px 'DM Sans',sans-serif;color:#f1ddba;border:1px solid rgba(228,208,176,.38);border-bottom-width:2px;background:rgba(12,17,18,.45);padding:4px 6px;border-radius:3px;margin:0 3px}.desktop-controls i{font-style:normal;color:#bb9157;padding:0 5px}.screen-cover{position:absolute;z-index:6;inset:0;display:grid;place-items:center;background:rgba(7,11,12,.62);backdrop-filter:blur(4px);transition:opacity .4s,visibility .4s}.screen-cover.hidden{opacity:0;visibility:hidden;pointer-events:none}.cover-card{text-align:center;width:min(460px,90vw);padding:32px 32px 24px;background:linear-gradient(145deg,rgba(29,36,37,.9),rgba(17,22,23,.94));border:1px solid rgba(231,184,102,.35);box-shadow:0 25px 90px rgba(0,0,0,.4);position:relative}.cover-card:before,.cover-card:after{content:'';position:absolute;width:25px;height:25px;border-color:#deb46d;border-style:solid}.cover-card:before{top:-1px;left:-1px;border-width:1px 0 0 1px}.cover-card:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}.cover-emblem{margin:0 auto 15px;width:40px;height:40px;border:1px solid rgba(231,184,102,.55);transform:rotate(45deg);display:grid;place-items:center;color:var(--gold);font-size:20px}.cover-emblem::first-letter{transform:rotate(-45deg)}.cover-card .eyebrow{margin-top:19px}.cover-card h1{font:800 clamp(39px,8vw,60px)/.88 'Barlow Condensed',sans-serif;letter-spacing:.08em;margin:15px 0;color:#f2e8d8}.cover-card h1 em{font-style:normal;color:#ddb36d}.cover-copy{max-width:330px;margin:0 auto;color:#b8b7ae;font-size:12px;line-height:1.75}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:28px;border:0;background:#d1a85f;color:#1b201f;margin:24px auto 19px;padding:14px 18px;min-width:220px;font:800 11px 'DM Sans',sans-serif;letter-spacing:.12em;cursor:pointer;transition:.2s}.primary-button:hover{background:#f0cc83;transform:translateY(-2px);box-shadow:0 8px 26px #ca995133}.primary-button b{font-size:18px}.cover-foot{font:700 8px 'DM Sans',sans-serif;letter-spacing:.18em;color:#898c83}.cover-foot span{color:#d4ad6b;padding:0 7px}.cover-foot i{font-style:normal;padding:0 6px;color:#d2a65f}.mobile-controls,.mobile-hint{display:none}
@media(max-width:700px){#game-shell{min-height:500px}.topbar{height:68px;padding:15px 18px}.brand{font-size:15px;gap:7px}.brand-mark{font-size:17px}.match-info{margin-left:27px}.eyebrow{font-size:7px}.match-title{font-size:10px}.icon-button{width:34px;height:34px}.combat-hud{top:82px;width:calc(100% - 34px);grid-template-columns:1fr 30px 1fr;gap:8px}.fighter-heading{display:block;margin-bottom:6px}.fighter-name{display:block;font-size:15px}.fighter-tag{display:block;font-size:6px;margin-top:2px;letter-spacing:.11em}.enemy-card .fighter-name{text-align:left}.enemy-card .fighter-heading{flex-direction:initial}.meter{height:11px}.stamina-meter{height:4px}.meter-label{font-size:6px}.vs-mark{font-size:9px}.bottom-bar{display:none}.mobile-controls{position:absolute;z-index:3;display:flex;left:0;right:0;bottom:max(15px,env(safe-area-inset-bottom));align-items:flex-end;justify-content:space-between;padding:0 18px;pointer-events:none}.move-pad{width:132px;height:132px;position:relative;pointer-events:auto;border-radius:50%;background:radial-gradient(circle,rgba(21,27,28,.34),rgba(12,17,18,.48));border:1px solid rgba(232,218,191,.13)}.move-btn{position:absolute;width:40px;height:40px;border:1px solid rgba(228,216,190,.25);border-radius:11px;background:rgba(31,39,39,.74);color:#e7d6b7;font-size:15px;touch-action:none;box-shadow:0 4px 12px #0004}.move-btn:active,.move-btn.pressed{background:#b88d4b;color:#151a1a}.move-up{top:5px;left:46px}.move-down{bottom:5px;left:46px}.move-left{left:5px;top:46px}.move-right{right:5px;top:46px}.pad-center{position:absolute;inset:0;display:grid;place-items:center;font-size:7px;letter-spacing:.1em;color:rgba(230,220,198,.36);pointer-events:none}.action-pad{display:flex;align-items:flex-end;gap:8px;pointer-events:auto;padding-bottom:5px}.action-btn{display:flex;flex-direction:column;justify-content:center;align-items:center;width:58px;height:58px;border-radius:50%;border:1px solid rgba(231,218,190,.34);background:rgba(24,30,30,.8);color:#ebdec5;touch-action:none;box-shadow:0 5px 16px #0005}.action-btn span{font-size:20px;line-height:22px}.action-btn small{font-size:7px;font-weight:700;letter-spacing:.07em;margin-top:2px}.action-btn:active,.action-btn.pressed{transform:scale(.92);background:#8d6540}.attack-btn{width:69px;height:69px;border-color:rgba(219,141,100,.68);background:rgba(99,51,42,.86);color:#ffe0bd;margin-bottom:16px}.attack-btn span{font-size:25px}.guard-btn{margin-bottom:3px}.dodge-btn{width:51px;height:51px;margin-bottom:27px}.dodge-btn span{font-size:19px}.mobile-hint{position:absolute;display:block;bottom:157px;left:50%;transform:translateX(-50%);font-size:7px;letter-spacing:.14em;color:rgba(235,226,206,.48);white-space:nowrap}.mobile-hint b{font-size:10px;color:#d7ac66;margin:0 3px}.round-toast{top:38%}.combat-callout{top:48%;font-size:19px}.cover-card{padding:27px 22px 20px}.cover-copy{font-size:11px;max-width:290px}.screen-cover{backdrop-filter:blur(3px)}}
@media(max-height:560px) and (max-width:700px){.topbar{height:56px;padding-top:8px;padding-bottom:8px}.combat-hud{top:65px}.move-pad{width:110px;height:110px}.move-btn{width:34px;height:34px}.move-up{left:37px}.move-down{left:37px}.move-left{top:37px}.move-right{top:37px}.action-btn{width:50px;height:50px}.attack-btn{width:59px;height:59px}.mobile-hint{bottom:130px}}
@media(min-width:701px){.mobile-controls,.mobile-hint{display:none!important}}

import * as THREE from 'three';

const mount=document.querySelector('#scene');
const scene=new THREE.Scene();
scene.background=new THREE.Color('#30383a');
scene.fog=new THREE.FogExp2('#30383a',0.027);
const camera=new THREE.PerspectiveCamera(38,innerWidth/innerHeight,.1,90);
camera.position.set(0,7.4,13.2);camera.lookAt(0,1.15,0);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xc8d4d1,0x42362e,2.1));
const keyLight=new THREE.DirectionalLight(0xffd49a,3.2);keyLight.position.set(-5,9,6);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-10;keyLight.shadow.camera.right=10;keyLight.shadow.camera.top=10;keyLight.shadow.camera.bottom=-10;scene.add(keyLight);
const rimLight=new THREE.DirectionalLight(0x9cb8b9,2.3);rimLight.position.set(5,5,-6);scene.add(rimLight);
const fireLight=new THREE.PointLight(0xff8a3d,22,10,2);fireLight.position.set(-4,2,-3);scene.add(fireLight);
const mat=(color,roughness=.7,metalness=0)=>new THREE.MeshStandardMaterial({color,roughness,metalness});
const stone=mat('#69655b'),stoneLight=mat('#81796b'),darkStone=mat('#333a3a'),gold=mat('#c99e56',.35,.72),silver=mat('#aeb8b6',.3,.8),darkSteel=mat('#536365',.32,.82),leather=mat('#342720'),redCloth=mat('#843e34'),blueCloth=mat('#345b61'),black=mat('#171d1e'),warm=mat('#f2ac55',.3,.25);
const floor=new THREE.Mesh(new THREE.CircleGeometry(22,80),mat('#383c39'));floor.rotation.x=-Math.PI/2;floor.position.y=-.14;floor.receiveShadow=true;scene.add(floor);
const arena=new THREE.Mesh(new THREE.CylinderGeometry(7.6,7.9,.35,64),stone);arena.position.y=-.18;arena.receiveShadow=true;arena.castShadow=true;scene.add(arena);
const top=new THREE.Mesh(new THREE.CircleGeometry(7.6,64),mat('#686253'));top.rotation.x=-Math.PI/2;top.position.y=.005;top.receiveShadow=true;scene.add(top);
for(let r of [2.4,4.7,7.27]){const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.035,6,96),r===7.27?gold:stoneLight);ring.rotation.x=Math.PI/2;ring.position.y=.025;scene.add(ring)}
for(let i=0;i<24;i++){let a=i*Math.PI/12;const p=new THREE.Mesh(new THREE.BoxGeometry(.035,.012,7.25),mat('#8c8069'));p.position.set(Math.sin(a)*3.65,.018,Math.cos(a)*3.65);p.rotation.y=a;p.material.transparent=true;p.material.opacity=.35;scene.add(p)}
// Broken citadel walls and torch-lit pillars frame the duel.
function pillar(x,z,h=4){const g=new THREE.Group();const base=new THREE.Mesh(new THREE.BoxGeometry(.95,.32,.95),darkStone);base.position.y=.16;g.add(base);const shaft=new THREE.Mesh(new THREE.CylinderGeometry(.31,.43,h,8),stoneLight);shaft.position.y=.32+h/2;g.add(shaft);const cap=new THREE.Mesh(new THREE.BoxGeometry(.85,.28,.85),stone);cap.position.y=.32+h;g.add(cap);g.position.set(x,0,z);g.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(g);return g}
for(const [x,z,h] of [[-8,-4,4.4],[8,-4,3.5],[-8,2,3],[8,2,4.4],[-6,-9,4],[6,-9,3.4]])pillar(x,z,h);
function brazier(x,z){const b=new THREE.Group();const bowl=new THREE.Mesh(new THREE.CylinderGeometry(.42,.24,.28,8),darkSteel);bowl.position.y=1.5;b.add(bowl);const stand=new THREE.Mesh(new THREE.CylinderGeometry(.12,.2,1.35,8),stoneLight);stand.position.y=.75;b.add(stand);for(let i=0;i<3;i++){const f=new THREE.Mesh(new THREE.ConeGeometry(.16+Math.random()*.08,.55+Math.random()*.32,7),new THREE.MeshBasicMaterial({color:i===1?0xffd178:0xf07836}));f.position.set((Math.random()-.5)*.17,1.93+Math.random()*.14,(Math.random()-.5)*.12);b.add(f)}b.position.set(x,0,z);scene.add(b);const l=new THREE.PointLight(0xff963c,25,9,2);l.position.set(x,2.35,z);scene.add(l);return l}
const torchLights=[brazier(-5.4,-3.5),brazier(5.4,-3.5)];
// Scattered masonry gives the arena a lived-in silhouette.
for(let i=0;i<15;i++){const a=i/15*Math.PI*2,r=8.5+Math.random()*1.8;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.35+Math.random()*.5,0),i%2?stone:darkStone);rock.position.set(Math.sin(a)*r,.15,Math.cos(a)*r-1);rock.scale.y=.5;rock.rotation.set(Math.random(),Math.random(),Math.random());rock.castShadow=true;rock.receiveShadow=true;scene.add(rock)}

function box(parent,w,h,d,material,x,y,z,rx=0,ry=0,rz=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.rotation.set(rx,ry,rz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function sphere(parent,r,material,x,y,z,sx=1,sy=1,sz=1){const m=new THREE.Mesh(new THREE.SphereGeometry(r,12,10),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function makeKnight(isPlayer){const root=new THREE.Group();scene.add(root);const body=new THREE.Group();root.add(body);const armor=isPlayer?silver:darkSteel,trim=isPlayer?gold:mat('#a14d3e',.4,.55),cloth=isPlayer?blueCloth:redCloth;
  // Hips, layered cuirass, and heraldic surcoat.
  box(body,.68,.38,.38,leather,0,1.02,0);box(body,.78,.85,.48,armor,0,1.53,0);box(body,.57,.53,.025,cloth,0,1.49,.253);box(body,.62,.1,.045,trim,0,1.18,.27);box(body,.5,.065,.045,gold,0,1.68,.275);
  sphere(body,.13,trim,-.2,1.58,.29,.8,.8,.4);sphere(body,.13,trim,.2,1.58,.29,.8,.8,.4);
  // Helmet, brow, narrow eye slit, and crest.
  const head=new THREE.Group();head.position.y=2.14;body.add(head);const helm=new THREE.Mesh(new THREE.SphereGeometry(.32,16,12),armor);helm.scale.set(.9,1.1,.9);helm.castShadow=true;head.add(helm);box(head,.45,.13,.42,armor,0,-.12,.08);box(head,.33,.045,.025,black,0,-.02,.302);box(head,.1,.17,.08,trim,0,-.16,.31);
  const plume=new THREE.Mesh(new THREE.ConeGeometry(.16,.55,7),trim);plume.position.set(0,.42,-.01);plume.rotation.z=-.12;head.add(plume);
  // Arms pivot at shoulders for weighty attacks.
  const arms=[];for(const side of [-1,1]){const arm=new THREE.Group();arm.position.set(side*.48,1.78,0);body.add(arm);sphere(arm,.22,armor,0,-.04,0,1,.9,1);box(arm,.22,.52,.24,armor,0,-.36,0);box(arm,.25,.18,.27,trim,0,-.63,.02);box(arm,.24,.17,.24,leather,0,-.76,.02);arms.push(arm)}
  // Leg plates, jointed for a recognizable walking gait.
  const legs=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.21,.92,0);body.add(leg);box(leg,.27,.54,.31,armor,0,-.28,0);box(leg,.3,.2,.34,trim,0,-.49,.015);box(leg,.34,.19,.52,leather,0,-.62,.08);legs.push(leg)}
  // Sword held in the right hand, with a bright edge and pommel.
  const weapon=new THREE.Group();weapon.position.set(.03,-.83,.08);arms[1].add(weapon);box(weapon,.1,.62,.12,leather,0,-.03,0);box(weapon,.43,.075,.15,gold,0,.26,0);box(weapon,.055,.83,.09,silver,0,.7,0);box(weapon,.025,.75,.095,mat('#e2e8df',.22,.9),-.026,.7,.005);const tip=new THREE.Mesh(new THREE.ConeGeometry(.05,.18,4),silver);tip.position.y=1.19;weapon.add(tip);sphere(weapon,.09,gold,0,-.39,0);
  const shield=new THREE.Group();shield.position.set(-.65,1.35,.03);body.add(shield);const shieldMesh=new THREE.Mesh(new THREE.CylinderGeometry(.43,.34,.15,6),isPlayer?darkSteel:armor);shieldMesh.rotation.x=Math.PI/2;shieldMesh.castShadow=true;shield.add(shieldMesh);sphere(shield,.12,trim,0,0,.1,1,1,.45);
  const shadow=new THREE.Mesh(new THREE.CircleGeometry(.65,20),new THREE.MeshBasicMaterial({color:0x101212,transparent:true,opacity:.38,depthWrite:false}));shadow.rotation.x=-Math.PI/2;shadow.position.y=.02;root.add(shadow);
  root.userData={body,head,arms,legs,weapon,shield,isPlayer};root.position.set(isPlayer?-1.8:1.8,0,0);return root}
const player=makeKnight(true),enemy=makeKnight(false);

