const player=makeKnight(true),enemy=makeKnight(false);
const $=s=>document.querySelector(s),cover=$('#screen-cover'),coverTitle=$('#cover-title'),coverCopy=$('#cover-copy'),startButton=$('#start-button');
const keys=new Set(),touchKeys=new Set(),touchActions=new Set();
const game={active:false,paused:false,over:false,playerHp:100,enemyHp:100,stamina:100,enemyGuard:100,playerAttack:0,attackCooldown:0,dodge:0,dodgeCooldown:0,guard:false,enemyState:'idle',enemyTimer:1.6,enemyDidHit:false,hitFlash:0,elapsed:0,shake:0,calloutTimer:0};
function setFill(id,value){$(id).style.width=Math.max(0,Math.min(100,value))+'%'}
function showMessage(text){const el=$('#combat-callout');el.textContent=text;el.classList.remove('pop');void el.offsetWidth;el.classList.add('pop')}
let audioContext=null;
function sound(freq,duration=.08,type='sawtooth',volume=.035){try{audioContext??=new AudioContext();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(volume,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.connect(gain);gain.connect(audioContext.destination);osc.start();osc.stop(audioContext.currentTime+duration)}catch{}}
function showCover(mode){cover.classList.remove('hidden');if(mode==='pause'){ $('#cover-kicker').textContent='TAKE A BREATH';coverTitle.innerHTML='THE DUEL<br><em>AWAITS.</em>';coverCopy.textContent='Catch your breath, then return to the Ashen Citadel.';startButton.querySelector('span').textContent='RESUME DUEL';startButton.querySelector('b').textContent='↗'}else if(mode==='win'||mode==='lose'){ $('#cover-kicker').textContent=mode==='win'?'THE CITADEL IS YOURS':'THE OATH ENDURES';coverTitle.innerHTML=mode==='win'?'THE WARDEN<br><em>FALLS.</em>':'RISE, <em>KNIGHT.</em>';coverCopy.textContent=mode==='win'?'The Warden yields. Your name will echo through the Ashen Citadel.':'The Warden holds the arena—for now. A true knight rises again.';startButton.querySelector('span').textContent='FIGHT AGAIN';startButton.querySelector('b').textContent='↻'}else{ $('#cover-kicker').textContent='A TRIAL BY STEEL';coverTitle.innerHTML='EARN YOUR<br><em>IRON OATH.</em>';coverCopy.textContent='Face the Warden in the Ashen Citadel. Read his stance, break his guard, and claim the arena.';startButton.querySelector('span').textContent='ENTER THE ARENA';startButton.querySelector('b').textContent='↗'}}
