function guardInput(on){game.guard=on&&game.active&&!game.paused&&!game.over}
function updateGame(dt){game.elapsed+=dt;const active=game.active&&!game.paused&&!game.over;game.attackCooldown=Math.max(0,game.attackCooldown-dt);game.dodgeCooldown=Math.max(0,game.dodgeCooldown-dt);game.dodge=Math.max(0,game.dodge-dt);game.hitFlash=Math.max(0,game.hitFlash-dt);game.shake=Math.max(0,game.shake-dt);if(active){
    const held=(name)=>moveMap[name].some(k=>keys.has(k))||touchKeys.has(name);const forward=(held('up')?1:0)-(held('down')?1:0),side=(held('right')?1:0)-(held('left')?1:0);const toEnemy=new THREE.Vector3(enemy.position.x-player.position.x,0,enemy.position.z-player.position.z).normalize();const right=new THREE.Vector3(toEnemy.z,0,-toEnemy.x);const move=toEnemy.multiplyScalar(forward).add(right.multiplyScalar(side));if(move.lengthSq()>1)move.normalize();const speed=(game.guard?1.35:game.dodge>0?7:3.25);player.position.addScaledVector(move,speed*dt);clampArena(player);
    if(game.guard){game.stamina=Math.max(0,game.stamina-17*dt);if(game.stamina<=0){game.guard=false;showMessage('GUARD BROKEN')}}else game.stamina=Math.min(100,game.stamina+22*dt);
    if(game.dodge>0){const retreat=new THREE.Vector3(player.position.x-enemy.position.x,0,player.position.z-enemy.position.z).normalize();player.position.addScaledVector(retreat,8*dt);clampArena(player)}
    if(game.playerAttack>0){game.playerAttack=Math.max(0,game.playerAttack-dt);const t=game.playerAttack/.48;player.userData.arms[1].rotation.x=t>.7?THREE.MathUtils.lerp(-.25,.25,(1-t)/.3):THREE.MathUtils.lerp(1.7,.25,t/.7);player.userData.arms[1].rotation.z=THREE.MathUtils.lerp(-1.05,0,Math.min(1,(.48-game.playerAttack)/.18));if(!game.playerHitDone&&game.playerAttack<.31&&game.playerAttack>.1){game.playerHitDone=true;if(distance()<3.05){if(game.enemyState==='guard'&&game.enemyGuard>8){game.enemyGuard=Math.max(0,game.enemyGuard-24);showMessage('BLOCKED');sound(430,.08,'triangle',.04);spawnSparks(enemy.position.clone().add(new THREE.Vector3(0,1.3,0)),0xd7b777)}else{damage('enemy',game.enemyState==='stagger'?30:24);if(game.enemyHp>0){game.enemyState='stagger';game.enemyTimer=.48}}}}}else{player.userData.arms[1].rotation.x=THREE.MathUtils.damp(player.userData.arms[1].rotation.x,0,9,dt);player.userData.arms[1].rotation.z=THREE.MathUtils.damp(player.userData.arms[1].rotation.z,0,8,dt)}
    const dx=player.position.x-enemy.position.x,dz=player.position.z-enemy.position.z,dist=Math.hypot(dx,dz);const eData=enemy.userData;eData.body.rotation.y=Math.atan2(dx,dz);player.userData.body.rotation.y=Math.atan2(enemy.position.x-player.position.x,enemy.position.z-player.position.z);
    if(game.enemyState==='idle'){game.enemyTimer-=dt;if(game.enemyTimer<=0)game.enemyState=dist>2.65?'approach':Math.random()<.25?'guard':'telegraph'}
    if(game.enemyState==='approach'){if(dist>2.45){enemy.position.x+=dx/(dist||1)*1.13*dt;enemy.position.z+=dz/(dist||1)*1.13*dt;clampArena(enemy)}else{game.enemyState='telegraph';game.enemyTimer=.72;game.enemyDidHit=false}}
    if(game.enemyState==='telegraph'){game.enemyTimer-=dt;if(game.enemyTimer<=0){game.enemyState='strike';game.enemyTimer=.32;game.enemyDidHit=false;sound(120,.08,'triangle',.02)}}
